\subsection{Definitions and mathematical statement}
\paragraph{Shared notation.}$\mathbb N$, $\mathbb Z$, $\mathbb Q$, $\mathbb R$, and $\mathbb C$ denote the natural numbers, integers, rationals, reals, and complex numbers, respectively. All additional parameters and hypotheses are specified in the question.


\paragraph{Statement recorded in the supplied source.}
For each $4\leq d\leq 63$, determine whether every bounded set $S\subseteq\mathbb R^d$ can be partitioned into at most $d+1$ subsets of diameter strictly smaller than $\operatorname{diam}(S)$.
\par\smallskip\textit{Formulation references:} \href{https://huggingface.co/datasets/ulamai/UnsolvedMath}{[S1]}, \href{https://doi.org/10.4171/owr/2024/3}{[S2]}.

\subsection{Short English statement}
For each $4\leq d\leq 63$, determine whether every bounded set $S\subseteq\mathbb R^d$ can be partitioned into at most $d+1$ subsets of diameter strictly smaller than $\operatorname{diam}(S)$.

\subsection{Sources}
\begin{itemize}
\item[S1] ULAM.AI and the UnsolvedMath Contributors, UnsolvedMath: A Curated Collection of Open Mathematics Problems, record 30005803 (OWR-14298163-006). Catalogue attribution under CC BY 4.0.
\url{https://huggingface.co/datasets/ulamai/UnsolvedMath}.
\item[S2] Original problem formulation and mathematical context.
\url{https://doi.org/10.4171/owr/2024/3}.
\end{itemize}
\label{end:30005803}

